//! ↩️ The displaced original singleton issues one genuine source while its pair and link arrays become the exact authored inverse.
use super::*;
impl<S:NetworkPath> NetworkPreparation<S>{
 fn old(&self)->Result<Option<&Network>,ValueError>{Ok(self.old_source.as_ref().ok_or_else(invalid)?.borrow().get().as_ref().map(SealedShared::get))}
 fn old_links(&self)->Result<RetainedCloneRef<'_,Vec<u32>>,ValueError>{if self.old()?.is_none(){return Err(invalid())}Ok(self.old_source.as_ref().ok_or_else(invalid)?.borrow().project(0,|v|v.as_ref().expect("admitted original network").get().link_ids.get()))}
 fn inverse_quote(&self,b:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase!=100||self.inverse_phase>=8||self.body.is_some_and(|v|v!=b){return Err(invalid())}match self.inverse_phase{
 0=>{let d=RetainedCloneSource::<OptionalNetwork>::owned_constructor_demand::<()>();Ok(RetirementDemand{copy_bytes:RetainedCloneSource::<OptionalNetwork>::constructor_copy_bytes()+2*size_of::<Option<OptionalNetwork>>()+2*size_of::<Option<RetainedCloneSource<OptionalNetwork>>>()+1,capacity_bytes:d.capacity_bytes,depth:d.depth.checked_add(1).ok_or_else(invalid)?,..Default::default()})},1=>Ok(scalar(2*size_of::<Option<NetworkInverse>>()+2*size_of::<usize>()+1)),2|3=>Ok(RetirementDemand{copy_bytes:2*size_of::<Vec<u32>>()+1,capacity_bytes:self.old()?.map_or(0,|v|v.zone_node_ids.get().len()).checked_mul(size_of::<u32>()).ok_or_else(invalid)?,depth:1,..Default::default()}),4=>Ok(scalar(2*size_of::<Pair>()+4*size_of::<u32>()+2*size_of::<usize>()+1)),5=>if self.old()?.is_some(){Ok(birth::<RetainedFieldPreparation<Vec<u32>>>())}else{Ok(scalar(1))},6=>nested(self.inverse_cursor.as_ref().ok_or_else(invalid)?.demand(self.old_links()?,b.saturating_sub(1))?,1),7=>nested(self.inverse_cursor.as_ref().ok_or_else(invalid)?.exchange_demand()?,2*size_of::<Vec<u32>>()+1),_=>Err(invalid())}}
 fn inverse_advance(&mut self,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.inverse_quote(body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=receipt(d);match self.inverse_phase{
 0=>{let extra=2*size_of::<Option<OptionalNetwork>>()+2*size_of::<Option<RetainedCloneSource<OptionalNetwork>>>()+1;let old=self.old.take().ok_or_else(invalid)?;match RetainedCloneSource::admit_owned(old,(),child(g,extra)){Ok((source,r))=>{*self.old_source=Some(source);p=add(r,extra)?;self.inverse_phase=1;},Err((error,old,()))=>{*self.old=Some(old);return Err(error)}}},
 1=>{let old=self.old()?;*self.inverse=Some(NetworkInverse{present:old.is_some(),zone_ids:Vec::new(),node_ids:Vec::new(),outdoor_node_id:old.map_or(0,|v|v.outdoor_node_id),link_ids:Vec::new()});self.inverse_index=0;self.inverse_phase=2;},2|3=>{let n=self.old()?.map_or(0,|v|v.zone_node_ids.get().len());let value=Vec::with_capacity(n);let inverse=self.inverse.as_mut().ok_or_else(invalid)?;if self.inverse_phase==2{inverse.zone_ids=value;self.inverse_phase=3;}else{inverse.node_ids=value;self.inverse_phase=4;}},
 4=>{let old=self.old()?;let n=old.map_or(0,|v|v.zone_node_ids.get().len());if self.inverse_index==n{self.inverse_phase=5;}else{let pair=old.ok_or_else(invalid)?.zone_node_ids.get()[self.inverse_index];let inverse=self.inverse.as_mut().ok_or_else(invalid)?;inverse.zone_ids.push(pair.0.0);inverse.node_ids.push(pair.1);self.inverse_index+=1;}},5=>{if self.old()?.is_some(){self.inverse_cursor=Some(Box::new(Default::default()));self.inverse_phase=6;}else{self.inverse_phase=8;}},
 6=>{let original=self.old_source.as_ref().ok_or_else(invalid)?.borrow().project(0,|v|v.as_ref().expect("admitted original network").get().link_ids.get());let c=self.inverse_cursor.as_mut().ok_or_else(invalid)?;p=add(c.advance(original,body.saturating_sub(1),child(g,1))?.progress(),1)?;if c.value().is_some(){self.inverse_phase=7;}},7=>{let extra=2*size_of::<Vec<u32>>()+1;let(value,r)=self.inverse_cursor.as_mut().ok_or_else(invalid)?.take(child(g,extra))?;self.inverse.as_mut().ok_or_else(invalid)?.link_ids=value.ok_or_else(invalid)?;p=add(r,extra)?;self.inverse_phase=8;},_=>return Err(invalid())}semio_framework_value::retained_clone::admit_retained_clone_progress(g,p,"original native network inverse")?;Ok(if self.inverse_phase==8{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
}
impl<S:NetworkPath> RowFieldPreparation for NetworkPreparation<S>{
 type Input=S::Payload;type Inverse=NetworkInverse;
 fn new()->Self{Self{authored:None,original:None,body:None,phase:0,index:0,outcome:None,closing:false,raw_pairs:ManuallyDrop::new(None),pairs:ManuallyDrop::new(None),links:ManuallyDrop::new(None),value:ManuallyDrop::new(None),old:ManuallyDrop::new(None),branch:ManuallyDrop::new(None),decision:ManuallyDrop::new(None),link_cursor:None,stage:None,output:None,old_source:ManuallyDrop::new(None),inverse:ManuallyDrop::new(None),inverse_cursor:None,inverse_phase:0,inverse_index:0,retirement:Default::default(),marker:Default::default()}}
 fn check(&self,p:RetainedCloneRef<'_,Self::Input>,key:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>)->Result<(),ValueError>{if key.is_some(){return Err(invalid())}self.check_sources(p,o)}
 fn demand(&self,p:RetainedCloneRef<'_,Self::Input>,_:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,b:usize)->Result<RetirementDemand,ValueError>{self.quote(p,o,b)}
 fn advance(&mut self,p:RetainedCloneRef<'_,Self::Input>,_:Option<RetainedCloneRef<'_,u32>>,o:RetainedCloneRef<'_,EnergyModelSnapshot>,b:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.step(p,o,b,g)}
 fn ready(&self)->bool{!self.closing&&self.phase==99}fn outcome(&self)->Option<RowOutcome>{self.outcome}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready()||self.decision.is_none(){return Err(invalid())}Ok(scalar(2*size_of::<Option<EnergyModelDiff>>()+1))}
 fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(EnergyModelDiff,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_mutation_demand_fits(d,g){return Ok(None)}self.phase=100;Ok(Some((self.decision.take().ok_or_else(invalid)?,receipt(d))))}
 fn inverse_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{self.inverse_quote(b)}fn prepare_inverse(&mut self,b:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.inverse_advance(b,g)}fn inverse_ready(&self)->bool{!self.closing&&self.phase==100&&self.inverse_phase==8&&self.inverse.is_some()}
 fn take_inverse_demand(&self)->Result<RetirementDemand,ValueError>{if !self.inverse_ready(){return Err(invalid())}Ok(scalar(2*size_of::<Option<NetworkInverse>>()+1))}
 fn take_inverse(&mut self,g:RetainedCloneGrant)->Result<Option<(NetworkInverse,RetainedCloneProgress)>,ValueError>{let d=self.take_inverse_demand()?;if !retained_mutation_demand_fits(d,g){return Ok(None)}self.phase=101;Ok(Some((self.inverse.take().ok_or_else(invalid)?,receipt(d))))}
 fn begin_close(&mut self){self.start_close()}fn close_demand(&self,b:usize)->Result<RetirementDemand,ValueError>{self.close_quote(b)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.close_advance(g)}fn terminal_is_empty(&self)->bool{self.empty()}
}
